  ('CLV_893A4F1B0002', 'DEMO', 'GROUP_ID', 'Group B', 'Group B', 4, TRUE, FALSE, FALSE)
ON CONFLICT (id) DO UPDATE SET
  option_label = EXCLUDED.option_label,
  is_active = TRUE;

